import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function Teachers() {
  // ඩේටාබේස් එකේ මුකුත් නැත්නම් පේන්න තාවකාලික දත්ත 
  const [lecturers, setLecturers] = useState([
    { name: "Mr. Amila Perera", subject: "Mathematics", qualifications: "BSc (Hons) in Mathematics", email: "amila@aurapen.lk", phone_number: "0771234567" },
    { name: "Ms. Nethmi Silva", subject: "Science", qualifications: "BSc in Natural Sciences", email: "nethmi@aurapen.lk", phone_number: "0719876543" }
  ]);

  useEffect(() => {
    axios.get('http://localhost:8081/api/view-teachers')
      .then(res => {
        // ඩේටාබේස් එකේ ගුරුවරු හිටියොත් විතරක් ඒ දත්ත ගන්නවා
        if(res.data && res.data.length > 0) {
            setLecturers(res.data);
        }
      })
      .catch(err => console.error("Error fetching teachers for website:", err));
  }, []);

  return (
    <div style={{ padding: '40px', backgroundColor: '#f4f7f5', minHeight: '100vh', fontFamily: 'sans-serif' }}>
      
      <div style={{ textAlign: 'center', marginBottom: '50px' }}>
        <h1 style={{ color: '#15803d', fontSize: '32px', fontWeight: '800', margin: 0 }}>Meet Our Expert Lecturers</h1>
        <p style={{ color: '#475569', fontSize: '16px', marginTop: '5px' }}>Highly Qualified Panel of Teachers at Aura Pen Education</p>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))', gap: '30px', maxWidth: '1200px', margin: '0 auto' }}>
        {lecturers.map((lec, index) => (
          <div key={index} style={{ backgroundColor: '#fff', borderRadius: '16px', overflow: 'hidden', boxShadow: '0 4px 20px rgba(0,0,0,0.02)', border: '1px solid #e2e8f0', display: 'flex', flexDirection: 'column' }}>
            
            <div style={{ height: '220px', backgroundColor: '#e2e8f0', display: 'flex', justifyContent: 'center', alignItems: 'center', overflow: 'hidden' }}>
              <img 
                src={`https://ui-avatars.com/api/?name=${encodeURIComponent(lec.name || 'Lecturer')}&background=dcfce7&color=15803d&size=150&bold=true`} 
                alt={lec.name} 
                style={{ width: '100%', height: '100%', objectFit: 'cover' }}
              />
            </div>

            <div style={{ padding: '20px', flex: 1, display: 'flex', flexDirection: 'column', gap: '8px' }}>
              <span style={{ backgroundColor: '#e0f2fe', color: '#0369a1', padding: '4px 10px', borderRadius: '6px', fontSize: '12px', fontWeight: '700', alignSelf: 'flex-start' }}>
                {lec.subject || 'Lecturer'}
              </span>

              <h3 style={{ margin: '5px 0 0 0', color: '#1e293b', fontSize: '18px', fontWeight: '700' }}>
                {lec.name}
              </h3>

              <p style={{ margin: '4px 0', color: '#047857', fontSize: '13px', fontWeight: '600', fontStyle: 'italic' }}>
                🎓 {lec.qualifications ? lec.qualifications : 'Highly Qualified Lecturer'}
              </p>
              
              <div style={{ margin: '10px 0 5px 0', color: '#64748b', fontSize: '14px', lineHeight: '1.6', flex: 1, borderTop: '1px dashed #e2e8f0', paddingTop: '10px' }}>
                <p style={{ margin: '2px 0' }}>📧 <b>Email:</b> {lec.email}</p>
                <p style={{ margin: '2px 0' }}>📞 <b>Contact:</b> {lec.phone_number}</p>
              </div>

              <div style={{ borderTop: '1px solid #f1f5f9', paddingTop: '10px', marginTop: '10px', color: '#15803d', fontWeight: '600', fontSize: '13px' }}>
                🟢 Aura Pen Verified Lecturer
              </div>
            </div>

          </div>
        ))}
      </div>
    </div>
  );
}
